import { describe, it, expect, afterEach } from 'vitest';
import { mkdtempSync, readFileSync, rmSync } from 'fs';
import { tmpdir } from 'os';
import { join } from 'path';
import { pathToFileURL } from 'url';

/**
 * The opencode seam of loop/stop steering, generated by src/cli/hooks.ts.
 *
 * The opencode client (qwen via the UAP proxy) has two failure modes the
 * Claude-style hooks cannot reach: (a) it never runs the .sh session-start
 * hook, so the cross-session loop-steer digest must come through the plugin's
 * session.created handler; (b) opencode cannot hard-block a stop, so the stop
 * side is a BOUNDED auto-continue resumed through the session API. These
 * tests generate the plugin exactly as `uap hooks` ships it and pin both.
 */
describe('opencode loop-steer plugin', () => {
  const dirs: string[] = [];
  afterEach(() => {
    for (const d of dirs) {
      try {
        rmSync(d, { recursive: true, force: true });
      } catch {
        /* ignore */
      }
    }
    dirs.length = 0;
  });

  const generate = async () => {
    const testDir = mkdtempSync(join(tmpdir(), `uap-oc-steer-${Date.now()}`));
    dirs.push(testDir);
    const { hooksCommand } = await import('../src/cli/hooks.js');
    await hooksCommand('install', { projectDir: testDir, target: 'opencode' });
    return testDir;
  };

  it('wires the loop-steer digest into session.created (timeout-bounded, fail-open)', async () => {
    const testDir = await generate();
    const plugin = readFileSync(join(testDir, '.opencode', 'plugin', 'uap-session-hooks.ts'), 'utf-8');
    // The opencode seam never runs the .sh session-start hook: the digest has
    // to come from the plugin, or recurring loop classes never reach a new
    // opencode session.
    expect(plugin).toContain('uap loops --steer');
    expect(plugin).toContain('<uap-loop-steer>');
    expect(plugin).toContain('session.created');
  });

  it('wires the bounded auto-continue into session.idle via the session API', async () => {
    const testDir = await generate();
    const plugin = readFileSync(join(testDir, '.opencode', 'plugin', 'uap-session-hooks.ts'), 'utf-8');
    expect(plugin).toContain('client.session.prompt');
    expect(plugin).toContain('UAP_AUTO_CONTINUE_MAX');
    expect(plugin).toContain('_uapShouldAutoContinue');
    // A proxy hard stop (ERROR-LOOP / LOOP-ESCALATE) must be detectable so
    // the nudge never resumes a session the guard deliberately killed — and
    // STICKY: matched at event time, never cleared by a later benign error.
    expect(plugin).toContain('session.error');
    expect(plugin).toMatch(/ERROR-LOOP|LOOP-ESCALATE/);
    expect(plugin).toContain('hardStops.add');
    expect(plugin).not.toContain('sessionErrors');
    // A garbage UAP_AUTO_CONTINUE_MAX must not delete the budget bound.
    expect(plugin).toContain('Number.isFinite(parsedMax)');
    // Verify output is untrusted build output: it rides the continuation
    // fenced, never bare under the instruction framing.
    expect(plugin).toContain('<failure-output>');
    // ONLY a genuine gate failure (verify exit 1) may continue — a future
    // edit to `!== 0` would auto-continue on verify timeouts (GNU timeout
    // RC 124, verify-internal RC 3), the exact case the design avoids.
    expect(plugin).toContain('if (res.exitCode === 1)');
    // An explicit human abort must never be fought by the nudge.
    expect(plugin).toMatch(/abort/i);
  });

  it('the repo\'s TRACKED plugin matches the generator (no silent drift)', async () => {
    const testDir = await generate();
    const generated = readFileSync(join(testDir, '.opencode', 'plugin', 'uap-session-hooks.ts'), 'utf-8');
    const tracked = readFileSync('.opencode/plugin/uap-session-hooks.ts', 'utf-8');
    expect(tracked).toBe(generated);
  });

  describe('_uapShouldAutoContinue (pure decision)', () => {
    type Decision = { proceed: boolean; reason: string };
    let decide: (input: {
      enabled: boolean;
      verifyFailed: boolean;
      lastErrorWasHardStop: boolean;
      continuesUsed: number;
      maxContinues: number;
      sameFailureAsLastContinue: boolean;
    }) => Decision;

    it('is exported by the generated plugin', async () => {
      const testDir = await generate();
      const mod = (await import(
        pathToFileURL(join(testDir, '.opencode', 'plugin', 'uap-session-hooks.ts')).href
      )) as { _uapShouldAutoContinue: typeof decide };
      decide = mod._uapShouldAutoContinue;
      expect(typeof decide).toBe('function');
    });

    it('proceeds exactly when the gates failed and no bound is hit', async () => {
      const testDir = await generate();
      const mod = (await import(
        pathToFileURL(join(testDir, '.opencode', 'plugin', 'uap-session-hooks.ts')).href
      )) as { _uapShouldAutoContinue: typeof decide };
      decide = mod._uapShouldAutoContinue;

      const base = {
        enabled: true,
        verifyFailed: true,
        lastErrorWasHardStop: false,
        continuesUsed: 0,
        maxContinues: 2,
        sameFailureAsLastContinue: false,
      };

      // The one path that resumes the session:
      expect(decide({ ...base }).proceed).toBe(true);
      expect(decide({ ...base }).reason).toContain('auto-continue 1/2');

      // Every bound below must refuse, each for its own named reason:
      expect(decide({ ...base, enabled: false }).proceed).toBe(false);
      expect(decide({ ...base, enabled: false }).reason).toContain('disabled');

      // Green gates = likely a human interrupt; never fight the operator.
      expect(decide({ ...base, verifyFailed: false }).proceed).toBe(false);
      expect(decide({ ...base, verifyFailed: false }).reason).toContain('left alone');

      // A proxy hard stop ended the session deliberately; resuming would
      // re-arm the guard and burn another prefill.
      expect(decide({ ...base, lastErrorWasHardStop: true }).proceed).toBe(false);
      expect(decide({ ...base, lastErrorWasHardStop: true }).reason).toContain('re-arm');

      // Budget bounds the meta-loop.
      expect(decide({ ...base, continuesUsed: 2, maxContinues: 2 }).proceed).toBe(false);
      expect(decide({ ...base, continuesUsed: 2, maxContinues: 2 }).reason).toContain('budget');
      expect(decide({ ...base, continuesUsed: 0, maxContinues: 0 }).proceed).toBe(false);
      // A garbage UAP_AUTO_CONTINUE_MAX parses to NaN — which must NOT make
      // every `>=` comparison false and silently delete the bound: the
      // decision normalizes it to the documented default of 2.
      const nanBudget = decide({ ...base, continuesUsed: 2, maxContinues: Number.NaN });
      expect(nanBudget.proceed).toBe(false);
      expect(nanBudget.reason).toContain('budget exhausted (2 per session)');
      expect(decide({ ...base, continuesUsed: 0, maxContinues: Number.NaN }).proceed).toBe(true);

      // A continue that produced no change must not repeat.
      expect(decide({ ...base, sameFailureAsLastContinue: true }).proceed).toBe(false);
      expect(decide({ ...base, sameFailureAsLastContinue: true }).reason).toContain('no progress');
    });

    it('is exported by the TRACKED plugin too (drift would break the import)', async () => {
      const mod = (await import(
        pathToFileURL(join('.opencode', 'plugin', 'uap-session-hooks.ts')).href
      )) as { _uapShouldAutoContinue: (i: unknown) => Decision };
      expect(typeof mod._uapShouldAutoContinue).toBe('function');
    });
  });
});
